-- PolicyAid CRM: complete database setup (generated by scripts/bundle-sql.mjs: do not edit by hand).
-- Contains 8 migrations, in order: 0001_schema.sql, 0002_functions.sql, 0003_rls.sql, 0004_uploads.sql, 0005_queue.sql, 0006_reports.sql, 0007_search_fix.sql, 0008_add_lead.sql
-- Paste the whole file into Supabase > SQL Editor > New query > Run. Run it once on a new project.

-- ============================================================ 0001_schema.sql
-- Dial Desk: core schema.
-- One lead = one vehicle (decision: a person with two vehicles appears as two leads).
-- Run order: 0001 (this), 0002 (functions), 0003 (RLS).

-- ---------------------------------------------------------------- enums
create type public.user_role as enum ('admin', 'manager', 'caller');

create type public.lead_status as enum (
  'new', 'no_answer', 'callback', 'interested', 'sold', 'not_interested', 'do_not_call'
);

-- ---------------------------------------------------------------- profiles
-- login_id is what people type; the auth email is derived from it (see README).
create table public.profiles (
  id          uuid primary key references auth.users (id) on delete cascade,
  login_id    text not null unique check (login_id ~ '^[a-z0-9._-]{3,32}$'),
  full_name   text not null check (length(trim(full_name)) between 2 and 80),
  role        public.user_role not null default 'caller',
  active      boolean not null default true,
  created_at  timestamptz not null default now()
);

-- ---------------------------------------------------------------- upload_batches
create table public.upload_batches (
  id           uuid primary key default gen_random_uuid(),
  uploaded_by  uuid not null references public.profiles (id),
  filename     text not null,
  total_rows   integer not null default 0 check (total_rows >= 0),
  added        integer not null default 0 check (added >= 0),
  duplicates   integer not null default 0 check (duplicates >= 0),
  invalid      integer not null default 0 check (invalid >= 0),
  created_at   timestamptz not null default now()
);

-- ---------------------------------------------------------------- leads
create table public.leads (
  id              uuid primary key default gen_random_uuid(),

  -- the 16 columns of the source sheet
  state           text,
  reg_no          text not null,
  rto_code        text,
  reg_date        date,
  name            text not null,                 -- OWNER NAME
  guardian_name   text,                          -- OWNER(S/W/D)
  address         text,
  engine_no       text,
  chassis_no      text,
  vehicle_make    text,
  vehicle_model   text,                          -- MODEL / VARIANT
  vehicle_class   text,
  fuel            text,
  sale_amount     numeric(14, 2) check (sale_amount is null or sale_amount >= 0),
  seat_capacity   integer check (seat_capacity is null or seat_capacity between 0 and 200),
  phone           text not null check (phone ~ '^[0-9]{10}$'),   -- MOBILE, normalised

  -- derived / working fields
  city            text,
  product         text not null default 'Motor renewal',
  source          text,
  -- Business rule from the owner: expiry = registration date + 5 days.
  policy_expiry   date generated always as (reg_date + 5) stored,

  assigned_to     uuid references public.profiles (id) on delete set null,
  status          public.lead_status not null default 'new',
  callback_at     timestamptz,
  attempts        integer not null default 0 check (attempts >= 0),
  last_called_at  timestamptz,
  dnd             boolean not null default false,
  batch_id        uuid references public.upload_batches (id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),

  -- one lead per vehicle; the registration number is the identity
  constraint leads_reg_no_key unique (reg_no),
  constraint leads_reg_no_clean check (reg_no = upper(reg_no) and reg_no ~ '^[A-Z0-9]{4,15}$'),
  constraint leads_dnd_consistent check (status <> 'do_not_call' or dnd)
);

create index leads_assigned_to_idx    on public.leads (assigned_to);
create index leads_status_idx         on public.leads (status);
create index leads_callback_at_idx    on public.leads (callback_at) where callback_at is not null;
create index leads_phone_idx          on public.leads (phone);
create index leads_batch_idx          on public.leads (batch_id);
create index leads_policy_expiry_idx  on public.leads (policy_expiry);
-- the caller queue: "my workable leads"
create index leads_queue_idx on public.leads (assigned_to, status, callback_at)
  where dnd = false and status <> 'do_not_call';

-- ---------------------------------------------------------------- call_logs (append-only)
create table public.call_logs (
  id           uuid primary key default gen_random_uuid(),
  lead_id      uuid not null references public.leads (id) on delete cascade,
  caller_id    uuid not null references public.profiles (id),
  outcome      public.lead_status not null check (outcome <> 'new'),
  note         text check (note is null or length(note) <= 1000),
  callback_at  timestamptz,
  created_at   timestamptz not null default now()
);

create index call_logs_lead_idx    on public.call_logs (lead_id, created_at desc);
create index call_logs_caller_idx  on public.call_logs (caller_id, created_at desc);
create index call_logs_created_idx on public.call_logs (created_at);

-- ---------------------------------------------------------------- audit_log (append-only)
create table public.audit_log (
  id          bigint generated always as identity primary key,
  actor_id    uuid,                     -- null only for system / service-role actions
  action      text not null,            -- upload | reassign | reassign_unworked | delete_lead | user_* | export | unblock_dnd
  entity      text not null,
  entity_id   text,
  details     jsonb not null default '{}'::jsonb,
  created_at  timestamptz not null default now()
);

create index audit_log_created_idx on public.audit_log (created_at desc);
create index audit_log_actor_idx   on public.audit_log (actor_id);

-- ============================================================ 0002_functions.sql
-- Dial Desk: helper functions, guard triggers, and the transactional RPCs.
-- Callers never write to leads or call_logs directly; they go through log_call().

-- ---------------------------------------------------------------- role helpers
-- SECURITY DEFINER so they can read profiles without recursing through RLS.
create or replace function public.auth_role()
returns public.user_role
language sql stable security definer set search_path = public
as $$ select role from public.profiles where id = auth.uid() and active $$;

create or replace function public.is_staff()
returns boolean
language sql stable security definer set search_path = public
as $$ select coalesce(public.auth_role() in ('admin', 'manager'), false) $$;

create or replace function public.is_admin()
returns boolean
language sql stable security definer set search_path = public
as $$ select coalesce(public.auth_role() = 'admin', false) $$;

-- ---------------------------------------------------------------- audit helper
create or replace function public.write_audit(
  p_action text, p_entity text, p_entity_id text, p_details jsonb
) returns void
language sql security definer set search_path = public
as $$
  insert into public.audit_log (actor_id, action, entity, entity_id, details)
  values (auth.uid(), p_action, p_entity, p_entity_id, coalesce(p_details, '{}'::jsonb));
$$;

-- ---------------------------------------------------------------- triggers
create or replace function public.touch_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end $$;

create trigger leads_touch before update on public.leads
  for each row execute function public.touch_updated_at();

-- Do-not-call is permanent: only an admin may lift it, and that is audited.
create or replace function public.guard_dnd()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if (old.dnd and not new.dnd) or (old.status = 'do_not_call' and new.status <> 'do_not_call') then
    if auth.uid() is not null and not public.is_admin() then
      raise exception 'dnd_locked' using errcode = 'P0001';
    end if;
    perform public.write_audit('unblock_dnd', 'lead', old.id::text, jsonb_build_object('reg_no', old.reg_no));
  end if;
  return new;
end $$;

create trigger leads_guard_dnd before update on public.leads
  for each row execute function public.guard_dnd();

-- Every deletion is recorded (single or bulk, whoever runs it).
create or replace function public.audit_lead_delete()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.audit_log (actor_id, action, entity, entity_id, details)
  values (auth.uid(), 'delete_lead', 'lead', old.id::text,
          jsonb_build_object('reg_no', old.reg_no, 'assigned_to', old.assigned_to, 'status', old.status));
  return old;
end $$;

create trigger leads_audit_delete before delete on public.leads
  for each row execute function public.audit_lead_delete();

create or replace function public.audit_upload()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.audit_log (actor_id, action, entity, entity_id, details)
  values (new.uploaded_by, 'upload', 'upload_batch', new.id::text,
          jsonb_build_object('filename', new.filename, 'total_rows', new.total_rows,
                             'added', new.added, 'duplicates', new.duplicates, 'invalid', new.invalid));
  return new;
end $$;

create trigger upload_batches_audit after insert on public.upload_batches
  for each row execute function public.audit_upload();

-- Append-only guards. call_logs may only disappear when its lead is deleted by an admin
-- (the cascade runs one trigger level deeper than a direct DELETE).
create or replace function public.block_log_changes()
returns trigger language plpgsql as $$
begin
  if tg_op = 'DELETE' and tg_table_name = 'call_logs' and pg_trigger_depth() > 1 then
    return old;
  end if;
  raise exception 'append_only' using errcode = 'P0001';
end $$;

create trigger call_logs_no_update before update on public.call_logs
  for each row execute function public.block_log_changes();
create trigger call_logs_no_delete before delete on public.call_logs
  for each row execute function public.block_log_changes();
create trigger audit_log_no_update before update on public.audit_log
  for each row execute function public.block_log_changes();
create trigger audit_log_no_delete before delete on public.audit_log
  for each row execute function public.block_log_changes();

-- ---------------------------------------------------------------- log_call
-- One transaction: write the history row, then update the lead. Never edits history.
-- Error messages are short codes; the app turns them into plain-language text.
create or replace function public.log_call(
  p_lead_id     uuid,
  p_outcome     public.lead_status,
  p_note        text default null,
  p_callback_at timestamptz default null
) returns public.leads
language plpgsql security definer set search_path = public
as $$
declare
  v_uid   uuid := auth.uid();
  v_role  public.user_role := public.auth_role();
  v_lead  public.leads;
  v_note  text := nullif(trim(coalesce(p_note, '')), '');
  v_cb    timestamptz := p_callback_at;
begin
  if v_uid is null or v_role is null then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;

  select * into v_lead from public.leads where id = p_lead_id for update;
  if not found then
    raise exception 'lead_not_found' using errcode = 'P0001';
  end if;
  if v_role = 'caller' and v_lead.assigned_to is distinct from v_uid then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;
  if v_lead.dnd or v_lead.status = 'do_not_call' then
    raise exception 'lead_blocked' using errcode = 'P0001';
  end if;
  if p_outcome = 'new' then
    raise exception 'invalid_outcome' using errcode = 'P0001';
  end if;
  if v_note is not null and length(v_note) > 1000 then
    raise exception 'note_too_long' using errcode = 'P0001';
  end if;

  -- sold / not interested / do not call never carry a callback
  if p_outcome in ('sold', 'not_interested', 'do_not_call') then
    v_cb := null;
  elsif p_outcome = 'callback' and v_cb is null then
    raise exception 'callback_required' using errcode = 'P0001';
  end if;
  if v_cb is not null and v_cb < now() - interval '5 minutes' then
    raise exception 'callback_in_past' using errcode = 'P0001';
  end if;

  insert into public.call_logs (lead_id, caller_id, outcome, note, callback_at)
  values (v_lead.id, v_uid, p_outcome, v_note, v_cb);

  update public.leads
     set status         = p_outcome,
         attempts       = attempts + 1,
         last_called_at = now(),
         callback_at    = v_cb,
         dnd            = dnd or p_outcome = 'do_not_call'
   where id = v_lead.id
   returning * into v_lead;

  -- Do-not-call belongs to the person, not the vehicle: block every lead on that number.
  if p_outcome = 'do_not_call' then
    update public.leads
       set dnd = true, status = 'do_not_call', callback_at = null
     where phone = v_lead.phone and status <> 'do_not_call';
    perform public.write_audit('do_not_call', 'lead', v_lead.id::text,
                               jsonb_build_object('reg_no', v_lead.reg_no));
  end if;

  return v_lead;
end $$;

-- ---------------------------------------------------------------- reassignment
create or replace function public.reassign_leads(p_lead_ids uuid[], p_to uuid)
returns integer
language plpgsql security definer set search_path = public
as $$
declare v_count integer;
begin
  if not public.is_staff() then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;
  if p_lead_ids is null or cardinality(p_lead_ids) = 0 or cardinality(p_lead_ids) > 5000 then
    raise exception 'invalid_selection' using errcode = 'P0001';
  end if;
  if p_to is not null and not exists (
    select 1 from public.profiles where id = p_to and role = 'caller' and active
  ) then
    raise exception 'invalid_target' using errcode = 'P0001';
  end if;

  update public.leads set assigned_to = p_to where id = any (p_lead_ids);
  get diagnostics v_count = row_count;

  perform public.write_audit('reassign', 'lead', null,
    jsonb_build_object('to', p_to, 'count', v_count, 'sample_ids', to_jsonb(p_lead_ids[1:20])));
  return v_count;
end $$;

-- "Unworked" = never called: status new and zero attempts.
create or replace function public.reassign_unworked(p_from uuid, p_to uuid)
returns integer
language plpgsql security definer set search_path = public
as $$
declare v_count integer;
begin
  if not public.is_staff() then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;
  if p_from is null or p_from is not distinct from p_to then
    raise exception 'invalid_selection' using errcode = 'P0001';
  end if;
  if p_to is not null and not exists (
    select 1 from public.profiles where id = p_to and role = 'caller' and active
  ) then
    raise exception 'invalid_target' using errcode = 'P0001';
  end if;

  update public.leads
     set assigned_to = p_to
   where assigned_to = p_from and status = 'new' and attempts = 0 and dnd = false;
  get diagnostics v_count = row_count;

  perform public.write_audit('reassign_unworked', 'profile', p_from::text,
    jsonb_build_object('from', p_from, 'to', p_to, 'count', v_count));
  return v_count;
end $$;

-- ---------------------------------------------------------------- execute grants
-- Internal helpers (write_audit, trigger functions) must not be callable by users.
revoke execute on all functions in schema public from public, anon, authenticated;
grant execute on function public.auth_role(), public.is_staff(), public.is_admin() to authenticated;
grant execute on function public.log_call(uuid, public.lead_status, text, timestamptz) to authenticated;
grant execute on function public.reassign_leads(uuid[], uuid) to authenticated;
grant execute on function public.reassign_unworked(uuid, uuid) to authenticated;

-- ============================================================ 0003_rls.sql
-- Dial Desk: Row Level Security. This is the real access control; the UI only mirrors it.
--   admin   : everything
--   manager : all leads and reports, uploads, reassignment; cannot delete leads or manage users
--   caller  : only leads assigned to them (and never DND leads); writes only through log_call()

alter table public.profiles       enable row level security;
alter table public.leads          enable row level security;
alter table public.call_logs      enable row level security;
alter table public.upload_batches enable row level security;
alter table public.audit_log      enable row level security;

-- Nothing is reachable without signing in.
revoke all on all tables in schema public from anon;
revoke all on all sequences in schema public from anon;

-- ---------------------------------------------------------------- profiles
-- Rows are created only by the server (service role) when an admin adds a user.
create policy profiles_select on public.profiles for select to authenticated
  using (id = auth.uid() or public.is_staff());

create policy profiles_admin_update on public.profiles for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- ---------------------------------------------------------------- leads
create policy leads_select_staff on public.leads for select to authenticated
  using (public.is_staff());

create policy leads_select_caller on public.leads for select to authenticated
  using (
    public.auth_role() = 'caller'
    and assigned_to = auth.uid()
    and dnd = false
    and status <> 'do_not_call'
  );

create policy leads_insert_staff on public.leads for insert to authenticated
  with check (public.is_staff());

create policy leads_update_staff on public.leads for update to authenticated
  using (public.is_staff()) with check (public.is_staff());

create policy leads_delete_admin on public.leads for delete to authenticated
  using (public.is_admin());

-- ---------------------------------------------------------------- call_logs
-- Read-only for everyone; rows are written by log_call() and can never be edited.
create policy call_logs_select_staff on public.call_logs for select to authenticated
  using (public.is_staff());

create policy call_logs_select_caller on public.call_logs for select to authenticated
  using (
    public.auth_role() = 'caller'
    and exists (
      select 1 from public.leads l
      where l.id = call_logs.lead_id and l.assigned_to = auth.uid()
    )
  );

-- ---------------------------------------------------------------- upload_batches
create policy batches_select_staff on public.upload_batches for select to authenticated
  using (public.is_staff());

create policy batches_insert_staff on public.upload_batches for insert to authenticated
  with check (public.is_staff() and uploaded_by = auth.uid());

-- ---------------------------------------------------------------- audit_log
create policy audit_select_staff on public.audit_log for select to authenticated
  using (public.is_staff());

-- ============================================================ 0004_uploads.sql
-- Dial Desk: upload batches are opened and closed through functions, so the audit entry is written
-- once, at the end, with the real number of leads added (counted here, not trusted from the browser).

alter table public.upload_batches add column finished_at timestamptz;

drop trigger if exists upload_batches_audit on public.upload_batches;
drop function if exists public.audit_upload();
drop policy if exists batches_insert_staff on public.upload_batches;

create or replace function public.begin_upload(p_filename text, p_total_rows integer)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare
  v_name text := left(trim(coalesce(p_filename, '')), 255);
  v_id   uuid;
begin
  if not public.is_staff() then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;
  if v_name = '' or p_total_rows is null or p_total_rows < 0 or p_total_rows > 100000 then
    raise exception 'invalid_upload' using errcode = 'P0001';
  end if;
  insert into public.upload_batches (uploaded_by, filename, total_rows)
  values (auth.uid(), v_name, p_total_rows)
  returning id into v_id;
  return v_id;
end $$;

create or replace function public.finish_upload(p_batch uuid, p_duplicates integer, p_invalid integer)
returns public.upload_batches
language plpgsql security definer set search_path = public
as $$
declare v_batch public.upload_batches;
begin
  if not public.is_staff() then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;

  select * into v_batch from public.upload_batches where id = p_batch for update;
  if not found or (v_batch.uploaded_by <> auth.uid() and not public.is_admin()) then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;
  if v_batch.finished_at is not null then
    raise exception 'already_finished' using errcode = 'P0001';
  end if;

  update public.upload_batches
     set added       = (select count(*) from public.leads where batch_id = p_batch),
         duplicates  = greatest(coalesce(p_duplicates, 0), 0),
         invalid     = greatest(coalesce(p_invalid, 0), 0),
         finished_at = now()
   where id = p_batch
   returning * into v_batch;

  perform public.write_audit('upload', 'upload_batch', v_batch.id::text,
    jsonb_build_object('filename', v_batch.filename, 'total_rows', v_batch.total_rows,
                       'added', v_batch.added, 'duplicates', v_batch.duplicates, 'invalid', v_batch.invalid));
  return v_batch;
end $$;

revoke execute on function public.begin_upload(text, integer), public.finish_upload(uuid, integer, integer)
  from public, anon;
grant execute on function public.begin_upload(text, integer) to authenticated;
grant execute on function public.finish_upload(uuid, integer, integer) to authenticated;

-- Which of these registration numbers are already in the system? Runs as the caller (RLS applies).
create or replace function public.existing_reg_nos(p_reg_nos text[])
returns setof text
language sql stable security invoker set search_path = public
as $$ select reg_no from public.leads where reg_no = any (p_reg_nos) $$;

revoke execute on function public.existing_reg_nos(text[]) from public, anon;
grant execute on function public.existing_reg_nos(text[]) to authenticated;

-- ============================================================ 0005_queue.sql
-- Dial Desk: the caller queue.
-- Ranking lives here, in one place, so paging stays correct for thousands of leads.
--   bucket 1  callback due now      (oldest callback first)
--   bucket 2  new                   (first loaded, first called)
--   bucket 3  no answer             (oldest attempt first)
--   bucket 4  later callbacks       (soonest first)
--   bucket 5  interested, nothing scheduled (worked; not in the to-do list)
--   bucket 6  sold / not interested (closed)
-- Do-not-call leads never appear: Row Level Security hides them from callers entirely.

create or replace function public.queue_bucket(
  p_status public.lead_status, p_callback_at timestamptz, p_now timestamptz default now()
) returns smallint
language sql immutable
as $$
  select (case
    when p_status in ('sold', 'not_interested', 'do_not_call') then 6
    when p_callback_at is not null and p_callback_at <= p_now then 1
    when p_status = 'new' then 2
    when p_status = 'no_answer' then 3
    when p_callback_at is not null then 4
    else 5
  end)::smallint
$$;

-- Search across name, city, registration number and (digits only) mobile number.
create or replace function public.lead_matches_search(
  p_search text, p_name text, p_city text, p_reg_no text, p_phone text
) returns boolean
language sql immutable
as $$
  with s as (
    select
      left(trim(coalesce(p_search, '')), 60) as raw
  ), p as (
    select
      raw,
      '%' || replace(replace(replace(raw, '\', '\\'), '%', '\%'), '_', '\_') || '%' as pattern,
      '%' || replace(replace(replace(upper(regexp_replace(raw, '[\s\-]', '', 'g')), '\', '\\'), '%', '\%'), '_', '\_') || '%' as reg_pattern,
      regexp_replace(raw, '\D', '', 'g') as digits
    from s
  )
  select raw = ''
      or p_name ilike pattern escape '\'
      or coalesce(p_city, '') ilike pattern escape '\'
      or p_reg_no ilike reg_pattern escape '\'
      or (length(digits) >= 3 and p_phone like '%' || digits || '%')
  from p
$$;

-- One page of the signed-in caller's queue. total_count is the size of the whole filtered list.
create or replace function public.my_queue(
  p_filter text default 'todo',
  p_search text default null,
  p_limit  integer default 30,
  p_offset integer default 0
) returns table (
  id uuid, name text, phone text, city text, reg_no text,
  vehicle_make text, vehicle_model text, status public.lead_status,
  callback_at timestamptz, attempts integer, last_called_at timestamptz,
  bucket smallint, total_count bigint
)
language sql stable security invoker set search_path = public
as $$
  with mine as (
    select l.*, public.queue_bucket(l.status, l.callback_at) as b
    from public.leads l
    where l.assigned_to = auth.uid()
      and l.dnd = false
      and l.status <> 'do_not_call'
      and public.lead_matches_search(p_search, l.name, l.city, l.reg_no, l.phone)
  )
  select m.id, m.name, m.phone, m.city, m.reg_no, m.vehicle_make, m.vehicle_model, m.status,
         m.callback_at, m.attempts, m.last_called_at, m.b, count(*) over () as total_count
  from mine m
  where case p_filter
    when 'todo'      then m.b in (1, 2, 3, 4)
    when 'due'       then m.b = 1
    when 'new'       then m.b = 2
    when 'no_answer' then m.b = 3
    when 'callbacks' then m.b = 4
    when 'interested' then m.b = 5
    when 'closed'    then m.b = 6
    else false
  end
  order by m.b,
           case when m.b in (1, 4) then m.callback_at end asc,
           case when m.b = 3 then m.last_called_at end asc nulls first,
           case when m.b in (5, 6) then m.last_called_at end desc nulls last,
           m.created_at asc, m.id asc
  limit least(greatest(coalesce(p_limit, 30), 1), 100)
  offset greatest(coalesce(p_offset, 0), 0)
$$;

create or replace function public.my_queue_counts(p_search text default null)
returns table (todo bigint, due bigint, new bigint, no_answer bigint, callbacks bigint, interested bigint, closed bigint)
language sql stable security invoker set search_path = public
as $$
  with mine as (
    select public.queue_bucket(l.status, l.callback_at) as b
    from public.leads l
    where l.assigned_to = auth.uid()
      and l.dnd = false
      and l.status <> 'do_not_call'
      and public.lead_matches_search(p_search, l.name, l.city, l.reg_no, l.phone)
  )
  select count(*) filter (where b in (1, 2, 3, 4)),
         count(*) filter (where b = 1),
         count(*) filter (where b = 2),
         count(*) filter (where b = 3),
         count(*) filter (where b = 4),
         count(*) filter (where b = 5),
         count(*) filter (where b = 6)
  from mine
$$;

-- Call history for a lead the caller owns (callers can't read other people's profiles directly).
create or replace function public.lead_history(p_lead_id uuid)
returns table (id uuid, outcome public.lead_status, note text, callback_at timestamptz,
               created_at timestamptz, caller_name text)
language sql stable security definer set search_path = public
as $$
  select c.id, c.outcome, c.note, c.callback_at, c.created_at, p.full_name
  from public.call_logs c
  join public.profiles p on p.id = c.caller_id
  where c.lead_id = p_lead_id
    and exists (
      select 1 from public.leads l
      where l.id = p_lead_id and (l.assigned_to = auth.uid() or public.is_staff())
    )
  order by c.created_at desc
  limit 100
$$;

-- Other vehicles registered to the same mobile number: minimal details, only for a lead you own.
create or replace function public.other_vehicles(p_lead_id uuid)
returns table (reg_no text, vehicle_make text, vehicle_model text, status public.lead_status)
language sql stable security definer set search_path = public
as $$
  select o.reg_no, o.vehicle_make, o.vehicle_model, o.status
  from public.leads me
  join public.leads o on o.phone = me.phone and o.id <> me.id
  where me.id = p_lead_id
    and (me.assigned_to = auth.uid() or public.is_staff())
  order by o.reg_no
  limit 20
$$;

revoke execute on function
  public.queue_bucket(public.lead_status, timestamptz, timestamptz),
  public.lead_matches_search(text, text, text, text, text),
  public.my_queue(text, text, integer, integer),
  public.my_queue_counts(text),
  public.lead_history(uuid),
  public.other_vehicles(uuid)
  from public, anon;
grant execute on function
  public.queue_bucket(public.lead_status, timestamptz, timestamptz),
  public.lead_matches_search(text, text, text, text, text),
  public.my_queue(text, text, integer, integer),
  public.my_queue_counts(text),
  public.lead_history(uuid),
  public.other_vehicles(uuid)
  to authenticated;

-- ============================================================ 0006_reports.sql
-- Dial Desk: manager reporting, the leads list with filters, and export auditing.
-- All of these refuse to run for callers (RLS would also limit them to their own rows).

-- ------------------------------------------------------------- dashboard
-- Two scopes, stated on screen:
--   pipeline  = leads LOADED in [p_from, p_to)   (null bounds = all time)
--   callers   = calls MADE in [p_from, p_to)
--   live      = callbacks due / overdue / unassigned right now, never date-filtered
create or replace function public.dashboard_summary(p_from timestamptz, p_to timestamptz)
returns jsonb
language plpgsql stable security invoker set search_path = public
as $$
declare
  v_result jsonb;
begin
  if not public.is_staff() then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;

  with cohort as (
    select l.status, l.attempts
    from public.leads l
    where (p_from is null or l.created_at >= p_from) and (p_to is null or l.created_at < p_to)
  ),
  by_status as (
    select coalesce(jsonb_object_agg(status, n), '{}'::jsonb) as j
    from (select status, count(*) as n from cohort group by status) s
  ),
  live as (
    select
      count(*) filter (where callback_at <= now() and dnd = false
                         and status not in ('sold', 'not_interested', 'do_not_call')) as due_now,
      count(*) filter (where assigned_to is null and dnd = false and status = 'new') as unassigned_new
    from public.leads
  ),
  act as (
    select c.caller_id,
           count(*) as calls,
           count(distinct c.lead_id) as called,
           count(distinct c.lead_id) filter (where c.outcome <> 'no_answer') as connected,
           count(distinct c.lead_id) filter (where c.outcome = 'interested') as interested,
           count(distinct c.lead_id) filter (where c.outcome = 'sold') as sold
    from public.call_logs c
    where (p_from is null or c.created_at >= p_from) and (p_to is null or c.created_at < p_to)
    group by c.caller_id
  ),
  asg as (
    select assigned_to as id,
           count(*) as assigned,
           count(*) filter (where callback_at < now() and dnd = false
                              and status not in ('sold', 'not_interested', 'do_not_call')) as overdue,
           count(*) filter (where status = 'new' and attempts = 0 and dnd = false) as unworked
    from public.leads
    where assigned_to is not null
    group by assigned_to
  ),
  callers as (
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', p.id, 'name', p.full_name, 'login_id', p.login_id, 'active', p.active,
             'assigned', coalesce(asg.assigned, 0), 'unworked', coalesce(asg.unworked, 0),
             'overdue', coalesce(asg.overdue, 0),
             'calls', coalesce(act.calls, 0), 'called', coalesce(act.called, 0),
             'connected', coalesce(act.connected, 0), 'interested', coalesce(act.interested, 0),
             'sold', coalesce(act.sold, 0)
           ) order by p.full_name), '[]'::jsonb) as j
    from public.profiles p
    left join act on act.caller_id = p.id
    left join asg on asg.id = p.id
    where p.role = 'caller' and (p.active or act.caller_id is not null or asg.id is not null)
  )
  select jsonb_build_object(
    'loaded',          (select count(*) from cohort),
    'called_once',     (select count(*) from cohort where attempts > 0),
    'sold',            (select count(*) from cohort where status = 'sold'),
    'by_status',       (select j from by_status),
    'callbacks_due',   (select due_now from live),
    'unassigned_new',  (select unassigned_new from live),
    'calls',           (select coalesce(sum(calls), 0) from act),
    'callers',         (select j from callers)
  ) into v_result;

  return v_result;
end $$;

-- ------------------------------------------------------------- leads list (manager view)
create or replace function public.staff_leads(
  p_assigned text default 'any',      -- 'any' | 'unassigned' | a caller's id
  p_status   text default 'any',      -- 'any' | a lead_status
  p_search   text default null,
  p_batch    uuid default null,
  p_limit    integer default 50,
  p_offset   integer default 0
) returns table (
  id uuid, name text, phone text, reg_no text, vehicle_make text, vehicle_model text,
  status public.lead_status, assigned_to uuid, assigned_name text, callback_at timestamptz,
  attempts integer, dnd boolean, created_at timestamptz, total_count bigint
)
language plpgsql stable security invoker set search_path = public
as $$
begin
  if not public.is_staff() then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;
  return query
    select l.id, l.name, l.phone, l.reg_no, l.vehicle_make, l.vehicle_model, l.status,
           l.assigned_to, p.full_name, l.callback_at, l.attempts, l.dnd, l.created_at,
           count(*) over () as total_count
    from public.leads l
    left join public.profiles p on p.id = l.assigned_to
    where (p_assigned = 'any'
           or (p_assigned = 'unassigned' and l.assigned_to is null)
           or l.assigned_to::text = p_assigned)
      and (p_status = 'any' or l.status::text = p_status)
      and (p_batch is null or l.batch_id = p_batch)
      and public.lead_matches_search(p_search, l.name, l.city, l.reg_no, l.phone)
    order by l.created_at desc, l.id
    limit least(greatest(coalesce(p_limit, 50), 1), 1000)
    offset greatest(coalesce(p_offset, 0), 0);
end $$;

-- Same filters, ids only: powers "select all N matching" for bulk actions (capped at 5,000).
create or replace function public.staff_lead_ids(
  p_assigned text default 'any', p_status text default 'any', p_search text default null, p_batch uuid default null
) returns setof uuid
language plpgsql stable security invoker set search_path = public
as $$
begin
  if not public.is_staff() then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;
  return query
    select l.id
    from public.leads l
    where (p_assigned = 'any'
           or (p_assigned = 'unassigned' and l.assigned_to is null)
           or l.assigned_to::text = p_assigned)
      and (p_status = 'any' or l.status::text = p_status)
      and (p_batch is null or l.batch_id = p_batch)
      and public.lead_matches_search(p_search, l.name, l.city, l.reg_no, l.phone)
    order by l.created_at desc, l.id
    limit 5000;
end $$;

-- How many never-called leads would "reassign all unworked from X" move?
create or replace function public.unworked_count(p_caller uuid)
returns bigint
language plpgsql stable security invoker set search_path = public
as $$
begin
  if not public.is_staff() then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;
  return (select count(*) from public.leads
          where assigned_to = p_caller and status = 'new' and attempts = 0 and dnd = false);
end $$;

-- ------------------------------------------------------------- export audit
create or replace function public.log_export(p_kind text, p_format text, p_rows integer, p_filters jsonb)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  if not public.is_staff() then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;
  if p_kind not in ('leads', 'call_logs') or p_format not in ('csv', 'xlsx') then
    raise exception 'invalid_export' using errcode = 'P0001';
  end if;
  perform public.write_audit('export', 'export', p_kind,
    jsonb_build_object('format', p_format, 'rows', greatest(coalesce(p_rows, 0), 0),
                       'filters', coalesce(p_filters, '{}'::jsonb)));
end $$;

revoke execute on function
  public.dashboard_summary(timestamptz, timestamptz),
  public.staff_leads(text, text, text, uuid, integer, integer),
  public.staff_lead_ids(text, text, text, uuid),
  public.unworked_count(uuid),
  public.log_export(text, text, integer, jsonb)
  from public, anon;
grant execute on function
  public.dashboard_summary(timestamptz, timestamptz),
  public.staff_leads(text, text, text, uuid, integer, integer),
  public.staff_lead_ids(text, text, text, uuid),
  public.unworked_count(uuid),
  public.log_export(text, text, integer, jsonb)
  to authenticated;

-- ------------------------------------------------------------- export source
-- Full lead rows with the same filters as the list, in stable pages (PostgREST caps a response at 1,000 rows).
create or replace function public.export_leads(
  p_assigned text default 'any', p_status text default 'any', p_search text default null, p_batch uuid default null,
  p_limit integer default 1000, p_offset integer default 0
) returns setof public.leads
language plpgsql stable security invoker set search_path = public
as $$
begin
  if not public.is_staff() then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;
  return query
    select l.*
    from public.leads l
    where (p_assigned = 'any'
           or (p_assigned = 'unassigned' and l.assigned_to is null)
           or l.assigned_to::text = p_assigned)
      and (p_status = 'any' or l.status::text = p_status)
      and (p_batch is null or l.batch_id = p_batch)
      and public.lead_matches_search(p_search, l.name, l.city, l.reg_no, l.phone)
    order by l.created_at, l.id
    limit least(greatest(coalesce(p_limit, 1000), 1), 1000)
    offset greatest(coalesce(p_offset, 0), 0);
end $$;

revoke execute on function public.export_leads(text, text, text, uuid, integer, integer) from public, anon;
grant execute on function public.export_leads(text, text, text, uuid, integer, integer) to authenticated;

-- ============================================================ 0007_search_fix.sql
-- Fix: a search like "R0007" (part of a registration number) was also matched against mobile numbers
-- because its digits were extracted. Digits only count as a phone search when the whole search is
-- a number (spaces, dashes, brackets and + allowed).
create or replace function public.lead_matches_search(
  p_search text, p_name text, p_city text, p_reg_no text, p_phone text
) returns boolean
language sql immutable
as $$
  with s as (
    select left(trim(coalesce(p_search, '')), 60) as raw
  ), p as (
    select
      raw,
      '%' || replace(replace(replace(raw, '\', '\\'), '%', '\%'), '_', '\_') || '%' as pattern,
      '%' || replace(replace(replace(upper(regexp_replace(raw, '[\s\-]', '', 'g')), '\', '\\'), '%', '\%'), '_', '\_') || '%' as reg_pattern,
      regexp_replace(raw, '\D', '', 'g') as digits,
      raw ~ '^[0-9 +().-]+$' as numeric_only
    from s
  )
  select raw = ''
      or p_name ilike pattern escape '\'
      or coalesce(p_city, '') ilike pattern escape '\'
      or p_reg_no ilike reg_pattern escape '\'
      or (numeric_only and length(digits) >= 3 and p_phone like '%' || digits || '%')
  from p
$$;

-- ============================================================ 0008_add_lead.sql
-- Dial Desk: callers can add a lead they have found themselves.
-- Only name and mobile number are compulsory, so the registration number becomes optional
-- (still unique when present; leads without one are matched by mobile number instead).

alter table public.leads alter column reg_no drop not null;
alter table public.leads drop constraint leads_reg_no_clean;
alter table public.leads add constraint leads_reg_no_clean
  check (reg_no is null or (reg_no = upper(reg_no) and reg_no ~ '^[A-Z0-9]{4,15}$'));

-- Search must cope with leads that have no registration number.
create or replace function public.lead_matches_search(
  p_search text, p_name text, p_city text, p_reg_no text, p_phone text
) returns boolean
language sql immutable
as $$
  with s as (
    select left(trim(coalesce(p_search, '')), 60) as raw
  ), p as (
    select
      raw,
      '%' || replace(replace(replace(raw, '\', '\\'), '%', '\%'), '_', '\_') || '%' as pattern,
      '%' || replace(replace(replace(upper(regexp_replace(raw, '[\s\-]', '', 'g')), '\', '\\'), '%', '\%'), '_', '\_') || '%' as reg_pattern,
      regexp_replace(raw, '\D', '', 'g') as digits,
      raw ~ '^[0-9 +().-]+$' as numeric_only
    from s
  )
  select raw = ''
      or p_name ilike pattern escape '\'
      or coalesce(p_city, '') ilike pattern escape '\'
      or coalesce(p_reg_no, '') ilike reg_pattern escape '\'
      or (numeric_only and length(digits) >= 3 and p_phone like '%' || digits || '%')
  from p
$$;

create or replace function public.add_lead(p_lead jsonb)
returns public.leads
language plpgsql security definer set search_path = public
as $$
declare
  v_uid   uuid := auth.uid();
  v_name  text := nullif(regexp_replace(trim(coalesce(p_lead ->> 'name', '')), '\s+', ' ', 'g'), '');
  v_phone text := regexp_replace(coalesce(p_lead ->> 'phone', ''), '\D', '', 'g');
  v_reg   text := nullif(upper(regexp_replace(coalesce(p_lead ->> 'reg_no', ''), '[\s\-._]', '', 'g')), '');
  v_date  date;
  v_sale  numeric;
  v_seats integer;
  v_lead  public.leads;
  t       text;
begin
  if v_uid is null or public.auth_role() is distinct from 'caller' then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;

  if v_name is null or length(v_name) > 120 then
    raise exception 'name_required' using errcode = 'P0001';
  end if;
  -- same clean-up as the app: +91 / 91 / 0091 / leading 0
  if length(v_phone) = 14 and left(v_phone, 4) = '0091' then v_phone := substr(v_phone, 5);
  elsif length(v_phone) = 12 and left(v_phone, 2) = '91' then v_phone := substr(v_phone, 3);
  elsif length(v_phone) = 11 and left(v_phone, 1) = '0' then v_phone := substr(v_phone, 2);
  end if;
  if v_phone !~ '^[6-9][0-9]{9}$' then
    raise exception 'invalid_phone' using errcode = 'P0001';
  end if;
  if v_reg is not null and v_reg !~ '^[A-Z0-9]{4,15}$' then
    raise exception 'invalid_reg_no' using errcode = 'P0001';
  end if;

  t := nullif(trim(coalesce(p_lead ->> 'reg_date', '')), '');
  if t is not null then
    begin
      v_date := t::date;
    exception when others then
      raise exception 'invalid_date' using errcode = 'P0001';
    end;
    if v_date < date '1980-01-01' or v_date > date '2100-12-31' then
      raise exception 'invalid_date' using errcode = 'P0001';
    end if;
  end if;

  t := nullif(trim(coalesce(p_lead ->> 'sale_amount', '')), '');
  if t is not null and t ~ '^[0-9]{1,12}(\.[0-9]{1,2})?$' then v_sale := t::numeric; end if;
  t := nullif(trim(coalesce(p_lead ->> 'seat_capacity', '')), '');
  if t is not null and t ~ '^[0-9]{1,3}$' and t::integer <= 200 then v_seats := t::integer; end if;

  -- Never add a number that has asked not to be called, whichever vehicle it was on.
  if exists (select 1 from public.leads where phone = v_phone and (dnd or status = 'do_not_call')) then
    raise exception 'lead_blocked' using errcode = 'P0001';
  end if;
  if v_reg is not null then
    if exists (select 1 from public.leads where reg_no = v_reg) then
      raise exception 'duplicate_vehicle' using errcode = 'P0001';
    end if;
  elsif exists (select 1 from public.leads where phone = v_phone) then
    raise exception 'duplicate_phone' using errcode = 'P0001';
  end if;

  insert into public.leads (
    name, phone, reg_no, reg_date, guardian_name, state, rto_code, address, city,
    engine_no, chassis_no, vehicle_make, vehicle_model, vehicle_class, fuel, sale_amount, seat_capacity,
    source, assigned_to
  ) values (
    v_name, v_phone, v_reg, v_date,
    left(nullif(trim(p_lead ->> 'guardian_name'), ''), 120),
    left(nullif(trim(p_lead ->> 'state'), ''), 60),
    upper(left(nullif(trim(p_lead ->> 'rto_code'), ''), 20)),
    left(nullif(trim(p_lead ->> 'address'), ''), 500),
    left(nullif(trim(p_lead ->> 'city'), ''), 80),
    upper(left(nullif(trim(p_lead ->> 'engine_no'), ''), 40)),
    upper(left(nullif(trim(p_lead ->> 'chassis_no'), ''), 40)),
    left(nullif(trim(p_lead ->> 'vehicle_make'), ''), 80),
    left(nullif(trim(p_lead ->> 'vehicle_model'), ''), 120),
    left(nullif(trim(p_lead ->> 'vehicle_class'), ''), 60),
    left(nullif(trim(p_lead ->> 'fuel'), ''), 30),
    v_sale, v_seats,
    'Added by caller', v_uid
  ) returning * into v_lead;

  perform public.write_audit('add_lead', 'lead', v_lead.id::text, jsonb_build_object('reg_no', v_lead.reg_no));
  return v_lead;
end $$;

revoke execute on function public.add_lead(jsonb) from public, anon;
grant execute on function public.add_lead(jsonb) to authenticated;
